-- ❌ Deadlock-prone: opposite lock orders
-- Session A
BEGIN TRAN;
  UPDATE Accounts SET Balance = Balance - 100 WHERE Id = 1;
  UPDATE Accounts SET Balance = Balance + 100 WHERE Id = 2;
COMMIT;

-- Session B (runs concurrently)
BEGIN TRAN;
  UPDATE Accounts SET Balance = Balance - 50 WHERE Id = 2;  -- waits for A
  UPDATE Accounts SET Balance = Balance + 50 WHERE Id = 1;  -- A waits for B: cycle
COMMIT;

-- ✅ Fixed: always lock accounts in ascending Id order
-- Both sessions: update the lower Id first, then the higher
BEGIN TRAN;
  UPDATE Accounts SET Balance = Balance - 100 WHERE Id = 1;
  UPDATE Accounts SET Balance = Balance + 100 WHERE Id = 2;
COMMIT;
-- Session B now queues behind A on row 1 instead of forming a cycle

